CREATE OR REPLACE FUNCTION public.award_joined_certificates_internal(p_profile uuid)
 RETURNS integer
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare
  made integer := 0;
begin
  insert into public.certificate_awards (design_id, profile_id, facts, serial)
